import java.util.*;
import java.nio.charset.*;
import java.nio.file.*;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in);int n=s.nextInt();List<String> lines=new ArrayList<>();for(int i=0;i<n;i++)lines.add(s.next());Path path=Path.of("data.txt");Files.write(path,lines,StandardCharsets.UTF_8);List<String> read=Files.readAllLines(path,StandardCharsets.UTF_8);for(int i=0;i<read.size();i++)System.out.println((i+1)+":"+read.get(i));} }

